    singles=[c[0] for c in cc if len(c)==1]
    templ=[]
    for c_ in cc:
        if len(c_)<=1: continue
        vals=Counter(g[a][b] for a,b in c_)
        # marker: unique color occurring once? or the distinct single-color cell
        uniq={v:c_ for v,c in vals.items() if c==1}
        if uniq:
            m=list(uniq.keys())[0]
            mc=list(uniq.values())[0]
            templ.append({'cells':c_,'m':mc,'mcol':m})
        else:
            # uniform: imagine marker at bottom-left of bbox
            rs=[a for a,_ in c_]; cs_=[b for _,b in c_]
            mr=(max(rs),min(cs_))
            templ.append({'cells':c_,'m':mr,'mcol':None})
    out=[r[:] for r in g]
    def paint(cells,color):
        for a,b in cells:
            if 0<=a<H and 0<=b<W and g[a][b]==bg:
                out[a][b]=color
    for ti,t in enumerate(templ):
        m=t['m']
        offs=[(a-m[0],b-m[1]) for a,b in t['cells'] if (a,b)!=m]
        for a in singles:
            if a==m: continue
            for dr,dc in offs:
                paint([(a[0]+dr,a[1]+dc)],ti+1)
    return out
