def comps(grid,bg):
    H,W=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            v=grid[r][c]
            if v==bg or (r,c) in seen: continue
            q=[(r,c)]; comp={(r,c)}; seen.add((r,c))
            while q:
                a,b=q.pop()
                for dx in(-1,0,1):
                    for dy in(-1,0,1):
                        nx,nb=a+dx,b+dy
                        if 0<=nx<H and 0<=nb<W and grid[nx][nb]==v and (nx,nb) not in comp:
                            comp.add((nx,nb)); q.append((nx,nb))
            out.append(comp)
    return out
