from collections import Counter
def comps_all(I,bg):
    H,W=len(I),len(I[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg and not seen[r][c]:
                q=[(r,c)]; seen[r][c]=True; cl=[]
                while q:
                    a,b=q.pop(); cl.append((a,b))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            n=(a+dx,b+dy)
                            if 0<=n[0]<H and 0<=n[1]<W and not seen[n[0]][n[1]] and I[n[0]][n[1]]!=bg:
                                seen[n[0]][n[1]]=True; q.append(n)
                out.append(cl)
    return out

def solve(I):
    H,W=len(I),len(I[0])
    bg=Counter(v for row in I for v in row).most_common(1)[0][0]
    Cs=comps_all(I,bg)
    singles={next(iter(c)) for c in Cs if len(c)==1}
    multic=[c for c in Cs if len(c)>1]
    O=[row[:] for row in I]
    for (mr,mc) in sorted(singles):
        # candidate multi comps by proximity
        best=None
        for o in multic:
            d=min(abs(mr-r)+abs(mc-c) for r,c in o)
            if best is None or d<best[0]: best=(d,o)
        d,o=best
        # marker must be adjacent-ish; skip if far? keep anyway
        col=Counter(I[r][c] for r,c in o if (r,c)!=(mr,mc)).most_common(1)[0][0]
        for r,c in o:
            if (r,c)==(mr,mc): continue
            O[r][c]=col
    return O
